CREATE TYPE public.app_role AS ENUM ('admin');
CREATE TABLE public.user_roles (user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE NOT NULL, role public.app_role NOT NULL, PRIMARY KEY (user_id, role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_roles ON public.user_roles FOR SELECT TO authenticated USING (user_id=auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid, public.app_role) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.has_role(uuid, public.app_role) TO authenticated, service_role;
CREATE FUNCTION public.assign_authorized_host() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF lower(NEW.email)='xmarcospaulo@gmail.com' AND NEW.email_confirmed_at IS NOT NULL THEN INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'admin') ON CONFLICT DO NOTHING; ELSE DELETE FROM public.user_roles WHERE user_id=NEW.id; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.assign_authorized_host() FROM PUBLIC;
CREATE TRIGGER assign_festa_host AFTER INSERT OR UPDATE OF email,email_confirmed_at ON auth.users FOR EACH ROW EXECUTE FUNCTION public.assign_authorized_host();
INSERT INTO public.user_roles(user_id,role) SELECT id,'admin'::public.app_role FROM auth.users WHERE lower(email)='xmarcospaulo@gmail.com' AND email_confirmed_at IS NOT NULL ON CONFLICT DO NOTHING;
CREATE TABLE public.parties (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), host_id uuid NOT NULL, code text UNIQUE NOT NULL DEFAULT upper(substr(replace(gen_random_uuid()::text,'-',''),1,6)), name text NOT NULL CHECK(char_length(name) BETWEEN 1 AND 80), status text NOT NULL DEFAULT 'ativa' CHECK(status IN ('ativa','encerrada')), playing boolean NOT NULL DEFAULT false, volume integer NOT NULL DEFAULT 70 CHECK(volume BETWEEN 0 AND 100), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.parties TO authenticated;
GRANT ALL ON public.parties TO service_role;
ALTER TABLE public.parties ENABLE ROW LEVEL SECURITY;
CREATE POLICY host_parties ON public.parties FOR ALL TO authenticated USING (host_id=auth.uid() AND public.has_role(auth.uid(),'admin')) WITH CHECK(host_id=auth.uid() AND public.has_role(auth.uid(),'admin'));
CREATE TABLE public.queue_entries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), party_id uuid NOT NULL REFERENCES public.parties(id) ON DELETE CASCADE, position bigint GENERATED ALWAYS AS IDENTITY, track jsonb NOT NULL, requested_by text NOT NULL DEFAULT 'Convidado' CHECK(char_length(requested_by) BETWEEN 1 AND 20), state text NOT NULL DEFAULT 'queued' CHECK(state IN ('queued','current','done')), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.queue_entries TO authenticated;
GRANT ALL ON public.queue_entries TO service_role;
GRANT USAGE,SELECT ON SEQUENCE public.queue_entries_position_seq TO authenticated,service_role;
ALTER TABLE public.queue_entries ENABLE ROW LEVEL SECURITY;
CREATE POLICY host_queue ON public.queue_entries FOR ALL TO authenticated USING (EXISTS(SELECT 1 FROM public.parties p WHERE p.id=party_id AND p.host_id=auth.uid() AND public.has_role(auth.uid(),'admin'))) WITH CHECK (EXISTS(SELECT 1 FROM public.parties p WHERE p.id=party_id AND p.host_id=auth.uid() AND public.has_role(auth.uid(),'admin')));
CREATE INDEX party_queue_order ON public.queue_entries(party_id,state,position);
CREATE UNIQUE INDEX one_current_track ON public.queue_entries(party_id) WHERE state='current';
CREATE FUNCTION public.party_snapshot(p_code text) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.parties; BEGIN SELECT * INTO p FROM public.parties WHERE code=upper(trim(p_code)); IF NOT FOUND THEN RETURN NULL; END IF; RETURN jsonb_build_object('id',p.id,'code',p.code,'name',p.name,'status',p.status,'playing',p.playing,'volume',p.volume,'queue',COALESCE((SELECT jsonb_agg(jsonb_build_object('id',q.id,'track',q.track,'requestedBy',q.requested_by,'state',q.state) ORDER BY q.position) FROM public.queue_entries q WHERE q.party_id=p.id AND q.state IN ('queued','current')),'[]'::jsonb)); END $$;
REVOKE ALL ON FUNCTION public.party_snapshot(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.party_snapshot(text) TO anon,authenticated,service_role;
CREATE FUNCTION public.add_party_request(p_code text,p_track jsonb,p_nickname text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.parties; result uuid; BEGIN SELECT * INTO p FROM public.parties WHERE code=upper(trim(p_code)) FOR UPDATE; IF NOT FOUND OR p.status<>'ativa' THEN RAISE EXCEPTION 'Festa indisponível ou encerrada'; END IF; IF p_track->>'id' NOT IN ('demo-1','demo-2','demo-3','demo-4','demo-5','demo-6','demo-7','demo-8') OR p_track->>'id' IS NULL OR char_length(p_track->>'title') NOT BETWEEN 1 AND 120 OR p_track->>'title' IS NULL THEN RAISE EXCEPTION 'Música inválida'; END IF; INSERT INTO public.queue_entries(party_id,track,requested_by) VALUES(p.id,p_track,COALESCE(NULLIF(left(trim(p_nickname),20),''),'Convidado')) RETURNING id INTO result; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.add_party_request(text,jsonb,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.add_party_request(text,jsonb,text) TO anon,authenticated,service_role;
CREATE FUNCTION public.control_party(p_id uuid,p_action text,p_value integer DEFAULT NULL,p_entry uuid DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.parties; next_id uuid; BEGIN SELECT * INTO p FROM public.parties WHERE id=p_id FOR UPDATE; IF NOT FOUND OR p.host_id IS DISTINCT FROM auth.uid() OR NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Acesso não autorizado'; END IF; IF p.status<>'ativa' THEN RAISE EXCEPTION 'Festa encerrada'; END IF; IF p_action='end' THEN UPDATE public.parties SET status='encerrada',playing=false WHERE id=p_id; ELSIF p_action='volume' THEN IF p_value IS NULL OR p_value NOT BETWEEN 0 AND 100 THEN RAISE EXCEPTION 'Volume inválido'; END IF; UPDATE public.parties SET volume=p_value WHERE id=p_id; ELSIF p_action='toggle' THEN UPDATE public.parties SET playing=NOT playing WHERE id=p_id; ELSIF p_action='remove' THEN DELETE FROM public.queue_entries WHERE id=p_entry AND party_id=p_id AND state='queued'; ELSIF p_action='skip' THEN UPDATE public.queue_entries SET state='done' WHERE party_id=p_id AND state='current'; SELECT id INTO next_id FROM public.queue_entries WHERE party_id=p_id AND state='queued' ORDER BY position LIMIT 1; IF next_id IS NOT NULL THEN UPDATE public.queue_entries SET state='current' WHERE id=next_id; END IF; UPDATE public.parties SET playing=(next_id IS NOT NULL) WHERE id=p_id; ELSE RAISE EXCEPTION 'Ação inválida'; END IF; END $$;
REVOKE ALL ON FUNCTION public.control_party(uuid,text,integer,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.control_party(uuid,text,integer,uuid) TO authenticated,service_role;